{
  "items": [
    {
      "name": "Nat.choose_le_two_pow",
      "module_name": "Mathlib.Data.Nat.Choose.Bounds",
      "kind": "theorem",
      "type": "∀ (n k : ℕ), n.choose k ≤ 2 ^ n"
    },
    {
      "name": "Nat.choose_succ_le_two_pow",
      "module_name": "Mathlib.Data.Nat.Choose.Bounds",
      "kind": "theorem",
      "type": "∀ (n k : ℕ), (n + 1).choose k ≤ 2 ^ n"
    },
    {
      "name": "Finset.prod_le_pow_card",
      "module_name": "Mathlib.Algebra.Order.BigOperators.Group.Finset",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {N : Type u_5} [inst : CommMonoid N] [inst_1 : PartialOrder N] [MulLeftMono N] (s : Finset ι)\n  (f : ι → N) (n : N), (∀ x ∈ s, f x ≤ n) → s.prod f ≤ n ^ s.card"
    },
    {
      "name": "Finset.max_prod_le",
      "module_name": "Mathlib.Algebra.Order.BigOperators.Group.Finset",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {M : Type u_4} [inst : CommMonoid M] [inst_1 : LinearOrder M] [IsOrderedMonoid M] {f g : ι → M}\n  {s : Finset ι}, max (s.prod f) (s.prod g) ≤ ∏ i ∈ s, max (f i) (g i)"
    },
    {
      "name": "Nat.choose_le_pow_div",
      "module_name": "Mathlib.Data.Nat.Choose.Bounds",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} [inst : Semifield α] [inst_1 : LinearOrder α] [IsStrictOrderedRing α] (r n : ℕ),\n  ↑(n.choose r) ≤ ↑n ^ r / ↑r.factorial"
    }
  ]
}
